{"path":"assets/css/styles.css","content":"/* Minimal, calm design — no external fonts */
:root{
  --bg:#fbfbfb; --card:#ffffff; --muted:#6b7280; --accent:#2b6cb0; --accent-2:#5a3db6;
  --radius:12px; --gap:18px; --max:1060px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:#111;background:var(--bg);margin:0}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.8),transparent);backdrop-filter:blur(4px);position:sticky;top:0;z-index:10;border-bottom:1px solid rgba(0,0,0,0.03)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:600;color:#111;text-decoration:none}
.main-nav{display:flex;gap:12px;align-items:center}
.main-nav a{color:#333;text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a.cta{background:var(--accent);color:#fff}
.menu-toggle{display:none}
.hero{padding:58px 0;background-size:300px 300px;background-repeat:repeat}
.hero-inner{display:flex;gap:28px;align-items:flex-start}
.hero-copy{flex:1}
.title{margin:0 0 8px;font-size:clamp(22px,3.6vw,36px)}
.lede{color:var(--muted);margin:0 0 18px}
.hero-ctas .btn{margin-right:8px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;border:1px solid rgba(0,0,0,0.06);background:var(--card);cursor:pointer;text-decoration:none;color:inherit}
.btn.primary{background:var(--accent);color:#fff;border:0}
.btn.outline{background:transparent;border:1px solid rgba(0,0,0,0.08)}
.contact-line{color:var(--muted);font-size:14px;margin-top:10px}
.card{background:var(--card);border-radius:var(--radius);padding:16px;box-shadow:0 6px 18px rgba(16,24,40,0.04)}
.hero-aside{width:320px}
.card h3{margin:0 0 8px}
input[type=text],input[type=number],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6e9ef;margin-bottom:10px}
textarea{min-height:80px}
.planner-actions,.wizard-actions{display:flex;gap:8px}
.pillars .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
.mt-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.case-notes .note{margin-top:10px}
.interactive .grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.faq dl{margin:0;padding:0}
.faq dt{font-weight:600;margin-top:12px}
.small{font-size:13px}
.muted{color:var(--muted)}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);padding:20px 0;margin-top:28px}
.foot-grid{display:flex;justify-content:space-between;gap:18px;align-items:center}
@media (max-width:900px){
  .hero-inner{flex-direction:column}
  .hero-aside{width:100%}
  .interactive .grid{grid-template-columns:1fr}
  .pillars .grid{grid-template-columns:1fr}
  .foot-grid{flex-direction:column;align-items:flex-start}
  .main-nav a{display:none}
  .menu-toggle{display:inline-block}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Small utilities
  function $id(id){return document.getElementById(id)}
  function copyText(txt){navigator.clipboard && navigator.clipboard.writeText(txt).catch(function(){alert('Copy failed — please copy manually.');});}

  // Planner
  var buildBtn=$id('planner-build');
  var copyBtn=$id('planner-copy');
  var output=$id('planner-output');
  buildBtn && buildBtn.addEventListener('click',function(){
    var goal=$id('planner-goal').value;
    var sessions=$id('planner-sessions').value;
    var length=$id('planner-length').value;
    var note=$id('planner-note').value || 'None';
    var summary=[
      'Session Plan — generated',
      'Primary focus: '+goal,
      'Planned sessions: '+sessions,
      'Session length: '+length,
      'Immediate notes: '+note,
      '',
      'Suggested topics for first session:',
      '- What brought you here and what feels most urgent?',
      '- What small change would feel like progress in 3 sessions?',
      '- Practical constraints or schedule preferences.'
    ].join('\n');
    output.value=summary;
  });
  copyBtn && copyBtn.addEventListener('click',function(){
    if(output.value && output.value.trim().length>0){copyText(output.value);}
  });

  // Quick Wizard
  var quickRun=$id('quick-run');
  var quickOut=$id('quick-output');
  quickRun && quickRun.addEventListener('click',function(){
    var a=$id('q1').value; var b=$id('q2').value; var c=$id('q3').value;
    var note='Quick Check — reflection\nPrimary concern: '+a+'\nDuration noted: '+b+'\nImpact on daily life: '+c+'\n\nSuggested prompts to bring to a consultation:\n- Can you describe when these feelings began or changed?\n- What has helped or not helped before?\n- What would you like to be different in the near term?\n';
    quickOut.value=note;
  });

  // Deep Wizard
  var deepRun=$id('deep-run');
  var deepCopy=$id('deep-copy');
  var deepOut=$id('deep-output');
  deepRun && deepRun.addEventListener('click',function(){
    var a=$id('d1').value||'<not entered>'; var b=$id('d2').value||'none'; var c=$id('d3').value||'<not entered>';
    var d=$id('d4').value||'none'; var e=$id('d5').value||'no immediate crisis';
    var questions=[];
    questions.push('Deep Check — reflections');
    questions.push('1) What matters most now: '+a);
    questions.push('2) What have you tried: '+b);
    questions.push('3) What would look like progress: '+c);
    questions.push('4) Practical barriers: '+d);
    questions.push('5) Safety/urgent note: '+e);
    questions.push('');
    questions.push('Suggested questions to ask a clinician:');
    questions.push('- How might we structure short-term work focused on the outcome I named?');
    questions.push('- What would you recommend to test in the first 2–3 sessions?');
    questions.push('- How will we measure progress in a way that feels meaningful to me?');
    deepOut.value=questions.join('\n');
  });
  deepCopy && deepCopy.addEventListener('click',function(){if(deepOut.value && deepOut.value.trim().length>0) copyText(deepOut.value);});

  // Small footer year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // Accessible menu toggle (small)
  var menuToggle=document.querySelector('.menu-toggle');
  var mainNav=document.querySelector('.main-nav');
  if(menuToggle && mainNav){
    menuToggle.addEventListener('click',function(){
      var open=this.getAttribute('aria-expanded')==='true';
      this.setAttribute('aria-expanded',!open);
      var links=mainNav.querySelectorAll('a');
      for(var i=0;i<links.length;i++){links[i].style.display = open ? 'none' : 'inline-block';}
    });
  }
})();"} 
